cat > /workspace/work/stress.py <<'EOF'
import json, random, sys, time

def case_backlog():
    # 40k enqueues into 1 bank, then 40k visits draining (large backlog service)
    ev = [["enqueue", i, 1, 100, i % 50] for i in range(40000)]
    ev += [["dequeue", 1]] * 20000
    return {"banks": 2, "load_balancers": 2, "fifo_bytes": 2147483647,
            "pifo_bytes": 2147483647, "refill_batch": 32, "sample_period": 100000,
            "borders": [0, 1000], "policy": {"kind": "sff"}, "events": ev}

def case_restore_storm():
    # snapshot a 32k backlog, then alternate restore+dequeue (refill 32 each)
    ev = [["enqueue", i, 1, 100, i % 50] for i in range(32000)]
    ev.append(["save", 1])
    for j in range(2000):
        ev.append(["restore", 1])
        ev.append(["dequeue", 1])
    return {"banks": 1, "load_balancers": 1, "fifo_bytes": 2147483647,
            "pifo_bytes": 2147483647, "refill_batch": 32, "sample_period": 100000,
            "borders": [0, 1000], "policy": {"kind": "fifo"}, "events": ev}

def case_save_storm():
    ev = []
    for i in range(30000):
        ev.append(["enqueue", i, 1, 100, i % 50])
        ev.append(["save", i % 7])
    return {"banks": 2, "load_balancers": 2, "fifo_bytes": 2147483647,
            "pifo_bytes": 2147483647, "refill_batch": 32, "sample_period": 5,
            "borders": [0, 25, 50, 75, 1000], "policy": {"kind": "sp",
            "levels": [[1, 3]]}, "events": ev}

def case_control():
    # samples + repartitions + saves within published control bounds
    rng = random.Random(7)
    ev = []
    for i in range(20000):
        ev.append(["enqueue", i, 1, 10, rng.randrange(1000)])
        if i % 3 == 0:
            ev.append(["sample"])
        if i % 40 == 0:
            ev.append(["repartition", [0, 137, 501, 1000]])
        if i % 9 == 0:
            ev.append(["save", i % 64])
        if i % 11 == 0:
            ev.append(["restore", i % 64 if (i % 64) < 64 else 0])
    return {"banks": 3, "load_balancers": 2, "fifo_bytes": 2147483647,
            "pifo_bytes": 2147483647, "refill_batch": 32, "sample_period": 100000,
            "borders": [0, 500, 1000], "policy": {"kind": "wfq",
            "weights": [[1, 5]]}, "events": ev}

def case_cancel_inspect():
    ev = [["enqueue", i, 1, 100, i % 50] for i in range(30000)]
    rng = random.Random(3)
    for j in range(30000):
        pid = rng.randrange(30000)
        ev.append(["cancel", pid] if j % 2 else ["inspect", pid])
    return {"banks": 4, "load_balancers": 4, "fifo_bytes": 2147483647,
            "pifo_bytes": 2147483647, "refill_batch": 32, "sample_period": 100000,
            "borders": [0, 1000], "policy": {"kind": "sff"}, "events": ev}

CASES = {"backlog": case_backlog, "restore_storm": case_restore_storm,
         "save_storm": case_save_storm, "control": case_control,
         "cancel_inspect": case_cancel_inspect}

if __name__ == "__main__":
    name = sys.argv[1]
    case = CASES[name]()
    req = {"runs": [case]}
    data = json.dumps(req).encode()
    sys.stdout.buffer.write(data)
EOF
cd /workspace/work && for c in backlog restore_storm save_storm control cancel_inspect; do
  /usr/bin/time -f "$c: %es wall, %Us user, %MKB mem" sh -c "python3 stress.py $c | python3 -I -B /workspace/submission/cli.py > /workspace/tmp/stress_$c.json" 2>&1 | tail -1
done
